// === Tab: mySketch ===
let Shader,displayShader;
let prev,curr,canv;
function setup() {
	canv=createCanvas(windowWidth,windowHeight,WEBGL);
	noStroke();
	prev=createGraphics(width,height);
	curr=createGraphics(width,height);
	prev.pixelDensity(1).noStroke();
	curr.pixelDensity(1).noStroke();

	background(0);
	for (let y=0;y<height;y++) {
		for (let x=0;x<width;x++) {
			prev.set(x,y,color(random(255)));
		}
	}
	prev.updatePixels();
	//frameRate(0);
}
function draw() {
	shader(Shader);
	Shader.setUniform('prev',prev);
	background(0).rect(0,0,width,height);
	curr.image(canv,0,0,width,height);
	let tmp=prev;
	prev=curr;
	curr=tmp;

	shader(displayShader);
	displayShader.setUniform('heightMap',curr);
	background(0).rect(0,0,width,height);
	if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) {prev.ellipse((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))),(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))),20);}
}
function preload() {
	Shader=new p5.Shader(this._renderer,`
		precision highp float;
		attribute vec3 aPosition;
		attribute vec2 aTexCoord;
		varying vec2 vTexCoord;
		void main() {
			vTexCoord=aTexCoord;
			vec4 positionVec4=vec4(aPosition,1.);
			positionVec4.xy=positionVec4.xy*2.-1.; 
			gl_Position=positionVec4;
		}
	`,`
		precision highp float;
		varying vec2 vTexCoord;
		const float width=${windowWidth}.;
		const float height=${windowHeight}.;
		uniform sampler2D prev;
		void main() {
			float x=vTexCoord.x*width;
			float y=height-vTexCoord.y*height;
			float val=0.;
			int n=0;
			for (int yy=-1;yy<=1;yy++) {
				for (int xx=-1;xx<=1;xx++) {
					if ((y+float(yy)>=0.&&y+float(yy)<height)&&(x+float(xx)>=0.&&x+float(xx)<width)) {
						if (n!=4) {
							val+=texture2D(prev,vec2((x+float(xx))/width,(y+float(yy))/height)).r;
						}
					} else {val+=1.;}
					n++;
				}
			}
			if (val<=4.) {val=texture2D(prev,vec2(x/width,y/height)).r-0.1;} 
			else {val=texture2D(prev,vec2(x/width,y/height)).r+0.1;}

			gl_FragColor=vec4(vec3(val),1.);
		}
	`);
	displayShader=new p5.Shader(this._renderer,`
		precision highp float;
		attribute vec3 aPosition;
		attribute vec2 aTexCoord;
		varying vec2 vTexCoord;
		void main() {
			vTexCoord=aTexCoord;
			vec4 positionVec4=vec4(aPosition,1.);
			positionVec4.xy=positionVec4.xy*2.-1.; 
			gl_Position=positionVec4;
		}
	`,`
		precision highp float;
		varying vec2 vTexCoord;
		const float width=${windowWidth}.;
		const float height=${windowHeight}.;
		uniform sampler2D heightMap;
		float rem(float x,float y) {
			x=abs(x);y=abs(y);
			for(int i=0;i<1;i+=0) {
				if(x<y) {break;}
				x-=y;
			}
			return x;
		}
		void main() {
			float x=vTexCoord.x*width;
			float y=height-vTexCoord.y*height;
			gl_FragColor=vec4(vec3(texture2D(heightMap,vec2(x/width,y/height)).r),1.);
		}
	`);
}

